/* Local full-length GRE mock interface. No exam answers are rendered before completion. */
(function(){
  'use strict';
  const KEY='gre-mock-exams-v1',C=window.GRECore,E=C.escape;
  let root,bridge,bank,questions,materials,sources,db,ready,visible=false,screen='setup',resultId=null,modal=null;
  let state={version:1,active:null,history:[],updatedAt:0},warning='',protectedStorage=false,originalBackup=null,saveQueue=Promise.resolve(),initializing=true,savedContent='';
  let lastClock=Date.now(),clockQuestion=null,timerHidden=false,order='random',preferUnseen=true,storageNotice=false;
  let practiceSubject='Verbal',subjectCount=20;
  const recording=new Set(),calc={value:'0',tokens:[],entry:'',replace:true,memory:0};
  const M=()=>window.GREMockCore;
  const clone=v=>JSON.parse(JSON.stringify(v));
  const $=s=>root?.querySelector(s);
  const notify=t=>bridge?.toast?bridge.toast(t):console.warn(t);
  const time=ms=>{const seconds=Math.max(0,Math.ceil(ms/1000));return Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');};
  const date=t=>new Date(t).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
  const words=t=>(t.trim().match(/\S+/g)||[]).length;
  const btn=(action,text,cls='secondary',extra='')=>`<button class="button ${cls}" data-mock-action="${action}" ${extra}>${text}</button>`;
  function indexBank(){bank=bridge.getBank();questions=new Map(bank.questions.map(q=>[q.question_id,q]));materials=new Map(bank.materials.map(m=>[m.id,m]));sources=new Map(bank.sources.map(s=>[s.id,s]));}
  function openDB(){return new Promise(resolve=>{try{const r=indexedDB.open(KEY,1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('data'))r.result.createObjectStore('data');};r.onsuccess=()=>resolve(r.result);r.onerror=()=>resolve(null);r.onblocked=()=>resolve(null);}catch{resolve(null);}});}
  function readDB(){return new Promise(resolve=>{if(!db)return resolve(null);try{const r=db.transaction('data').objectStore('data').get('progress');r.onsuccess=()=>resolve(r.result);r.onerror=()=>resolve(null);}catch{resolve(null);}});}
  function writeDB(snapshot){return new Promise((resolve,reject)=>{if(!db)return reject(Error('无本地数据库'));try{const tx=db.transaction('data','readwrite');tx.objectStore('data').put(snapshot,'progress');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||Error('本地数据库保存失败'));tx.onabort=()=>reject(tx.error||Error('本地数据库保存中止'));}catch(e){reject(e);}});}
  function save({preserveTimestamp=initializing,silent=false,force=false}={}){if(protectedStorage)return Promise.resolve(false);const content=JSON.stringify({...state,updatedAt:0}),changed=content!==savedContent;if(!changed&&!force)return saveQueue;if(changed&&!preserveTimestamp)state.updatedAt=Date.now();savedContent=content;const snapshot=clone(state);if(changed&&!silent&&!preserveTimestamp)window.GREPortable?.changed();let localOK=false;try{localStorage.setItem(KEY,JSON.stringify(snapshot));localOK=true;}catch{warning='浏览器快速存储不可用，正在尝试本地数据库。请及时导出模考备份。';}
    saveQueue=saveQueue.then(()=>writeDB(snapshot)).then(()=>true).catch(()=>{if(!localOK){warning='当前浏览器无法持久保存模考，请立即导出备份；关闭页面可能丢失本次记录。';if(!storageNotice){notify(warning);storageNotice=true;}}return localOK;});return saveQueue;}
  function validateProgress(raw,validationBank=bank){if(!raw||raw.version!==1||!Array.isArray(raw.history))throw Error('不是有效的阅间模考备份。');const out={version:1,active:null,history:[],updatedAt:Number(raw.updatedAt)||0},ids=new Set();
    for(const item of raw.history){const exam=M().restore(item,validationBank);if(!exam.endedAt)throw Error('历史记录包含未完成考试，原文件未导入。');if(ids.has(exam.id))throw Error('备份中考试 ID 重复。');ids.add(exam.id);out.history.push(exam);}
    if(raw.active){const exam=M().restore(raw.active,validationBank);if(ids.has(exam.id))throw Error('当前考试与历史记录 ID 重复。');if(exam.endedAt)out.history.push(exam);else out.active=exam;}
    return out;
  }
  async function initialize(){indexBank();db=await openDB();let local=null;try{const text=localStorage.getItem(KEY);if(text){originalBackup=text;local=JSON.parse(text);}}catch{warning='模考存档无法读取。原存档已保留，请先导出原存档检查。';protectedStorage=true;}
    const durable=await readDB();let raw=durable&&(!local||durable.updatedAt>local.updatedAt)?durable:local;
    if(raw)try{state=validateProgress(raw);}catch(e){protectedStorage=true;originalBackup=typeof raw==='string'?raw:JSON.stringify(raw);warning=e.message+' 原存档不会被覆盖，请导出原存档检查。';}
    savedContent=JSON.stringify({...state,updatedAt:0});if(!protectedStorage){checkClock();for(const exam of state.history)record(exam);}lastClock=Date.now();initializing=false;
    setInterval(checkClock,500);window.addEventListener('beforeunload',()=>{accrue();save();});
    window.addEventListener('storage',event=>{if(event.key!==KEY||!event.newValue||protectedStorage)return;try{const incoming=validateProgress(JSON.parse(event.newValue));if(incoming.updatedAt>state.updatedAt){state=incoming;savedContent=JSON.stringify({...state,updatedAt:0});window.GREPortable?.changed();clockQuestion=null;lastClock=Date.now();if(visible)render();notify('已同步另一个窗口的模考进度。建议只在一个窗口作答。');}}catch{notify('另一个窗口写入的模考存档无法读取，当前作答已保留。');}});
  }
  function current(){const exam=state.active;if(!exam||exam.endedAt)return null;const section=exam.sections[exam.currentSection],id=section.ids[exam.index],q=questions.get(id);if(!q)return null;const r=exam.responses[id]||={selected:[],text:'',marked:false,elapsedMs:0};return {exam,section,q,r};}
  function accrue(){const now=Date.now(),c=current();if(c&&visible&&screen==='exam'&&clockQuestion===c.q.question_id){c.r.elapsedMs=Math.max(0,c.r.elapsedMs||0)+Math.max(0,Math.min(now,c.section.deadline)-lastClock);}lastClock=now;clockQuestion=c?.q.question_id||null;}
  function resultOf(action,...args){const exam=state.active,result=M()[action](exam,bank,...args);if(result&&result.id===exam.id&&Array.isArray(result.sections))state.active=result;return state.active;}
  function record(exam){if(!bridge?.recordExam||recording.has(exam.id))return;recording.add(exam.id);Promise.resolve(bridge.recordExam(clone(exam))).catch(()=>{recording.delete(exam.id);warning='模考已单独保存，但汇入综合学习记录失败；重新进入本页将重试。';notify(warning);});}
  function archive(){const exam=state.active;if(!exam?.endedAt)return;const at=state.history.findIndex(e=>e.id===exam.id);if(at>=0)state.history[at]=clone(exam);else state.history.unshift(clone(exam));resultId=exam.id;state.active=null;screen='result';modal=null;document.body.classList.remove('mock-running');save();record(exam);}
  function checkClock(){if(!state.active||protectedStorage)return;const old=state.active.currentSection;accrue();resultOf('tick',Date.now());if(state.active?.endedAt){const previousScreen=screen,previousResult=resultId;archive();if(previousScreen!=='exam'){screen=previousScreen;resultId=previousResult;}if(visible)render();return;}if(state.active.currentSection!==old){modal=null;calcReset();timerHidden=false;clockQuestion=null;save();if(visible){render();if(screen==='exam')notify('本节时间已到，已进入下一节。');}}updateClock();}
  function updateClock(){const c=current(),el=$('#mock-timer');if(el&&c){el.textContent=timerHidden?'计时中':time(c.section.deadline-Date.now());el.classList.toggle('urgent',c.section.deadline-Date.now()<300000);el.setAttribute('aria-label','本节剩余 '+time(c.section.deadline-Date.now()));}const text=$('#mock-save-note');if(text)text.textContent=warning||'作答自动保存在本机';}
  function heading(title,desc,kicker='GRE · SUBJECT PRACTICE'){return `<header class="mock-heading"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1><p class="description">${desc}</p></div><span class="pill">VERBAL / QUANT</span></header>`;}
  function setupHTML(){const practice=bridge.getPracticeSession?.();return heading('选好科目，直接开始刷题。','默认 Verbal，随机抽题。按自己的节奏练，每题提交后查看答案与解析。')+`
    <section class="panel subject-practice-panel">
      <div class="subject-choice-grid" role="group" aria-label="选择刷题科目">
        ${[{id:'Verbal',title:'语文',description:'阅读理解 · 文本填空 · 六选二',tag:'RC / TC / SE'},{id:'Quant',title:'数学',description:'数量比较 · 选择题 · 数值填空 · 图表题',tag:'QC / CHOICE / NUMERIC / DI'}].map(s=>`<button class="subject-choice ${practiceSubject===s.id?'selected':''}" data-subject-choice="${s.id}" aria-pressed="${practiceSubject===s.id}"><span class="subject-choice-top"><span class="eyebrow">${s.tag}</span><span class="subject-choice-indicator" aria-hidden="true">${practiceSubject===s.id?'✓':''}</span></span><strong>${s.id}<span>${s.title}</span></strong><span class="subject-choice-description">${s.description}</span></button>`).join('')}
      </div>
      <div class="subject-practice-controls"><div><h2>这次想练多少题？</h2><div class="subject-count-options" role="group" aria-label="选择题量">${[10,20,30,50].map(n=>`<button class="subject-count ${subjectCount===n?'selected':''}" data-subject-count="${n}" aria-pressed="${subjectCount===n}">${n} 题</button>`).join('')}<label class="subject-count-custom" for="subject-count">自定义 <input id="subject-count" type="number" min="1" max="100" step="1" value="${subjectCount}" required aria-label="自定义题量，1 至 100 题"><span>题</span></label></div><p class="tiny">不限时 · 随机抽取已核验题目 · 学习记录自动保存</p></div>${btn('start-subject','随机开始 '+practiceSubject+' →','subject-start')}</div>
    </section>
    ${practice?`<section class="subject-practice-resume"><span>上次的 <strong>${E(practice.subject)}</strong> 练习已作答 ${E(practice.answered)} / ${E(practice.count)} 题</span>${btn('resume-subject','继续上次 '+E(practice.subject)+' →','secondary small')}</section>`:''}
    ${warning?`<div class="platform-warning subject-legacy-warning">${E(warning)}${originalBackup&&protectedStorage?btn('export-original','导出原存档','secondary small'):''}<p>旧模考存档问题不影响上方的随机刷题。</p></div>`:''}
    ${state.active?`<section class="mock-resume subject-legacy-resume panel"><div><p class="eyebrow">PREVIOUS MOCK EXAM</p><h2>还有一场旧模考</h2><p class="muted">${date(state.active.startedAt)} 开始 · ${E(state.active.sections[state.active.currentSection].title)}。原模考计时仍按开始时间继续。</p></div>${btn('resume','继续旧模考 →','secondary small')}</section>`:''}
    <details class="subject-legacy-history"><summary>旧模考记录与备份${state.history.length?' · '+state.history.length+' 场':''}</summary><div class="row mock-history-tools">${btn('export','导出模考备份','secondary small')}${btn('import','导入模考备份','secondary small')}</div>${state.history.length?`<div class="mock-history">${state.history.map(exam=>{const s=examSummary(exam);return `<button class="mock-history-item" data-mock-history="${E(exam.id)}"><span><strong>${date(exam.startedAt)}</strong><small>${exam.aborted?'已中止':'已完成'} · ${time(exam.endedAt-exam.startedAt)}</small></span><span><strong>${s.correct} / ${s.total}</strong><small>客观题原始正确数 · 查看复盘 →</small></span></button>`;}).join('')}</div>`:'<p class="muted">暂无旧模考记录。新的随机练习会记录在「学习分析」中。</p>'}</details>
    <input id="mock-import-file" type="file" accept=".json,application/json" hidden>`;}
  function imageHTML(items,review=false){return (items||[]).filter(i=>C.localAsset(i.src)).map(i=>`<figure class="mock-figure"><button class="mock-image-button" data-mock-image="${E(i.src)}" aria-label="放大原题图"><img src="${E(i.src)}" alt="${E(review?i.caption||'原资料图像':'原题图像，点击放大')}" loading="eager"></button><figcaption>${review&&i.caption?E(i.caption)+' · ':''}点击放大原题图</figcaption></figure>`).join('');}
  function markedText(text,marks){const ranges=[];for(const mark of marks||[]){const s=typeof mark==='string'?mark:mark?.text;if(!s)continue;const i=text.indexOf(s);if(i>=0)ranges.push([i,i+s.length]);}ranges.sort((a,b)=>a[0]-b[0]);let out='',at=0;for(const [start,end]of ranges){if(start<at)continue;out+=E(text.slice(at,start))+'<mark>'+E(text.slice(start,end))+'</mark>';at=end;}return out+E(text.slice(at));}
  function materialHTML(q,r,review=false){const m=materials.get(q.material_id);if(!m)return '';const paragraphs=m.paragraphs?.length?m.paragraphs:[m.text||''];let rendered=paragraphs.map(t=>`<p>${markedText(t,q.highlights||m.highlights)}</p>`).join('');
    if(q.question_type==='RCSentence'&&!review){const options=q.options||[],allMatched=options.every(o=>paragraphs.some(p=>p.includes(o.text)));if(allMatched){rendered=paragraphs.map(p=>{const matches=options.map(o=>({o,at:p.indexOf(o.text)})).filter(x=>x.at>=0).sort((a,b)=>a.at-b.at);let out='',at=0;for(const x of matches){if(x.at<at)continue;out+=E(p.slice(at,x.at))+`<button class="mock-sentence ${r.selected.includes(x.o.id)?'selected':''}" data-mock-option="${E(x.o.id)}" aria-pressed="${r.selected.includes(x.o.id)}">${E(x.o.text)}</button>`;at=x.at+x.o.text.length;}return '<p>'+out+E(p.slice(at))+'</p>';}).join('');}}
    return `<article class="panel mock-material"><p class="eyebrow">${q.category==='Verbal'?'READ THE PASSAGE':'SHARED MATERIAL'}</p>${imageHTML(m.images,review)}<div class="passage-text" lang="en">${rendered}</div></article>`;
  }
  function optionHTML(o,r,disabled=false){const selected=r.selected?.includes(o.id);return `<button class="option ${selected?'selected':''}" data-mock-option="${E(o.id)}" aria-pressed="${!!selected}" ${disabled?'disabled':''}><span class="option-key">${E(o.label||o.id)}</span><span class="option-text" lang="en">${E(o.text)}</span></button>`;}
  function interaction(q,r){const mode=C.mode(q);if(mode==='writing')return `<label class="field mock-writing-label">YOUR RESPONSE<textarea class="essay-editor" id="mock-answer-text" data-mock-question="${E(q.question_id)}" spellcheck="false" autocomplete="off" autocorrect="off" autocapitalize="off" aria-label="Issue 作文">${E(r.text)}</textarea></label><div class="essay-meta"><span id="mock-word-count">${words(r.text)} words</span><span>原生剪切、复制、粘贴、撤销快捷键可用</span></div>`;
    if(mode==='numeric')return `<label class="numeric-entry"><input id="mock-answer-text" data-mock-question="${E(q.question_id)}" type="text" inputmode="decimal" autocomplete="off" value="${E(r.text)}" aria-label="数值答案" placeholder="按原题输入数字或分数"><small>${E(q.numeric_format?.unit||'数字或分数')}${q.numeric_format?.precision?'<br>'+E(q.numeric_format.precision):''}</small></label>`;
    if(q.blank_groups?.length>1)return `<div class="blanks-layout" style="--blanks:${q.blank_groups.length}">${q.blank_groups.map((g,i)=>`<section class="blank-group"><h3>Blank ${i+1}</h3><div class="options">${g.options.map(o=>optionHTML(o,r)).join('')}</div></section>`).join('')}</div>`;
    return `<div class="options">${(q.options?.length?q.options:q.blank_groups?.[0]?.options||[]).map(o=>optionHTML(o,r)).join('')}</div>`;
  }
  function examHTML(){const c=current();if(!c)return setupHTML();const {exam,section,q,r}=c,m=C.mode(q);const completed=section.ids.filter(id=>C.complete(questions.get(id),exam.responses[id]||{selected:[],text:''})).length;clockQuestion=q.question_id;lastClock=Date.now();return `<div class="mock-topbar"><div><p class="eyebrow">阅间 · GRE MOCK</p><h1>${E(section.title)}</h1><span class="tiny">第 ${exam.currentSection+1} / 5 节 · ${section.minutes} 分钟</span></div><div class="mock-time-block"><span class="tiny">SECTION TIME LEFT</span><strong id="mock-timer">${time(section.deadline-Date.now())}</strong><button class="text-link" data-mock-action="toggle-time">${timerHidden?'显示倒计时':'隐藏倒计时'}</button></div></div><div class="mock-section-strip">${exam.sections.map((s,i)=>`<span class="${i===exam.currentSection?'active':s.endedAt?'done':''}">${i+1}. ${E(s.subject==='AWA'?'Issue':s.title)}</span>`).join('')}</div>${warning?`<div class="platform-warning">${E(warning)}</div>`:''}<div class="mock-toolbar"><div class="row"><span class="tag">Question ${exam.index+1} / ${section.ids.length}</span>${m!=='writing'?btn('mark',r.marked?'★ 已标记':'☆ 标记复查',r.marked?'small':'secondary small','aria-pressed="'+!!r.marked+'"'):''}${m!=='writing'?btn('review','本节总览','secondary small'):''}</div><div class="row">${section.subject==='Quant'?btn('calculator','计算器','secondary small'):''}${btn('setup','返回模考入口','ghost small')}${btn('end-exam','中止全考','ghost small')}</div></div><div class="mock-question-layout ${q.material_id?'has-material':''} ${m==='writing'?'is-writing':''}">${materialHTML(q,r)}<section class="panel mock-question"><p class="eyebrow">${m==='writing'?'ANALYZE AN ISSUE':'QUESTION '+(exam.index+1)}</p><div class="mock-prompt" lang="en">${E(q.question_content)}</div>${imageHTML(q.images)}${q.quantities?`<div class="quantity-pair"><div><h3>Quantity A</h3><p>${E(q.quantities.a)}</p></div><div><h3>Quantity B</h3><p>${E(q.quantities.b)}</p></div></div>`:''}${q.instructions?`<div class="writing-instructions" lang="en">${E(q.instructions)}</div>`:''}${m!=='writing'?`<p class="question-kind">${q.question_type==='RCSentence'?'选择文章中符合要求的句子，或点击下方对应句子。':{pair:'Select exactly two answer choices.',blanks:'Select one entry for each blank.',multiple:'Select all correct answer choices.',single:'Select one answer choice.',numeric:'Enter your answer as instructed.'}[m]||''}</p>`:''}${m!=='writing'?interaction(q,r):''}</section>${m==='writing'?`<section class="panel mock-writing">${interaction(q,r)}</section>`:''}</div><div class="mock-bottom-bar"><div class="row">${btn('previous','← 上一题','secondary',exam.index===0?'disabled':'')}<span class="tiny">${completed} / ${section.ids.length} 已作答</span>${exam.index<section.ids.length-1?btn('next','下一题 →',''):btn('review',m==='writing'?'检查作文':'本节总览','secondary')}</div>${btn('end-section',exam.currentSection===4?'提交本节并完成模考':'提交本节 →','')}</div><p class="tiny mock-save-note" id="mock-save-note">作答自动保存在本机</p>`;}
  function sectionSummary(exam,s){const item=M().summary(exam,bank).sections.find(x=>x.id===s.id);return {...item,correct:item.correct||0,wrong:item.wrong||0,written:s.subject==='AWA'?item.answered:0,started:s.startedAt!==null,total:s.subject==='AWA'?0:item.total};}
  function examSummary(exam){const total=M().summary(exam,bank).total;return {...total,total:total.visited};}
  function sourceLink(id,pages,label){const source=sources.get(id),url=source?.url||source?.reader?.url;if(!C.localAsset(url))return '';const page=pages?.[0]||1;return `<a class="text-link" target="_blank" rel="noopener" href="${E(url+(url.endsWith('.pdf')?'#page='+(source.reader?.pageMap?.[page]||page):''))}">${E(label||source.title||id)}${pages?.length?' · 第 '+E(pages.join('、'))+' 页':''} ↗</a>`;}
  function answerText(q,r){if(C.mode(q)==='writing'||C.mode(q)==='numeric')return r?.text||'未作答';const opts=q.blank_groups?.length?q.blank_groups.flatMap(g=>g.options):q.options||[];return r?.selected?.length?r.selected.map(id=>{const o=opts.find(o=>o.id===id);return id+(o?' · '+o.text:'');}).join('\n'):'未作答';}
  function resultHTML(){const exam=state.history.find(e=>e.id===resultId);if(!exam){screen='setup';return setupHTML();}const total=examSummary(exam);return heading(exam.aborted?'这次暂停在这里，也留下清楚的记录。':'完成了。现在，回看每一步。',`${date(exam.startedAt)} · ${exam.aborted?'中止模考':'整套模考'} · 总用时 ${time(exam.endedAt-exam.startedAt)}`,'MOCK EXAM · REVIEW')+`<div class="row mock-result-tools">${btn('setup','← 返回模考入口','secondary')}${btn('export','导出模考备份','secondary')}</div><div class="stats"><div class="stat"><label>客观题原始正确数</label><strong>${total.correct} / ${total.total}</strong><small>已进入的语文与数学节</small></div><div class="stat"><label>答错</label><strong>${total.wrong}</strong><small>未将漏答重复计入</small></div><div class="stat"><label>漏答</label><strong>${total.omitted}</strong><small>已进入节内未作答题</small></div><div class="stat"><label>写作</label><strong>已保存</strong><small>不自动评分</small></div></div><div class="mock-method"><p>这是本地题库模考的原始结果，不是 GRE 官方分数。未进入的节不计为错题；多空题和多选题按完整答案计分。</p></div><div class="table-scroll"><table class="platform-table mock-results-table"><thead><tr><th>分节</th><th>正确</th><th>答错</th><th>漏答</th><th>实际用时</th><th>状态</th></tr></thead><tbody>${exam.sections.map(s=>{const t=sectionSummary(exam,s);return `<tr><td>${E(s.title)}</td><td>${s.subject==='AWA'?'—':t.started?t.correct:'—'}</td><td>${s.subject==='AWA'?'—':t.started?t.wrong:'—'}</td><td>${s.subject==='AWA'?'—':t.started?t.omitted:'—'}</td><td>${s.startedAt?time((s.endedAt||exam.endedAt)-s.startedAt):'—'}</td><td>${!s.startedAt?'未进入':s.subject==='AWA'?t.written?'作文已保存':'未写作':s.endReason==='timeout'?'时间到':s.endReason==='abort'?'中止':'已提交'}</td></tr>`;}).join('')}</tbody></table></div><h2 class="section-heading">逐题复盘</h2><div class="stack">${exam.sections.filter(s=>s.startedAt).map(s=>`<section><h3 class="mock-review-section">${E(s.title)}</h3>${s.ids.map((id,i)=>reviewQuestion(exam,s,id,i)).join('')}</section>`).join('')}</div>`;}
  function reviewQuestion(exam,section,id,i){const q=questions.get(id),r=exam.responses[id]||{selected:[],text:''},writing=q.category==='AWA',answered=!!(r.selected?.length||r.text?.trim()),right=C.grade(q,r);return `<details class="panel mock-review-question"><summary>第 ${i+1} 题 · ${E(C.types[q.question_type])} · ${writing?'作文':!answered?'未作答':right===true?'正确':right===false?'错误':'不计判分'}${r.marked?' · ★ 标记':''}</summary><div class="mock-prompt" lang="en">${E(q.question_content)}</div>${q.instructions?`<p class="writing-instructions">${E(q.instructions)}</p>`:''}${materialHTML(q,r,true)}${imageHTML(q.images,true)}${!writing?`<div class="mock-review-options">${(q.blank_groups?.length?q.blank_groups.flatMap(g=>g.options):q.options||[]).map(o=>`<p><strong>${E(o.id)}</strong> ${E(o.text)}</p>`).join('')}</div>`:''}<div class="mock-your-answer"><strong>${writing?'你的作文':'你的答案'}</strong><p>${E(answerText(q,r))}</p>${writing?btn('export-essay','导出作文 TXT','secondary small',`data-mock-exam="${E(exam.id)}" data-mock-qid="${E(id)}"`):''}</div>${!writing?`<div class="platform-answer ${right===false?'wrong':''}"><h3>原资料答案：${E((q.correct_answer||[]).join('、')||q.raw_answer||'未附')}</h3>${imageHTML(q.explanation_images,true)}${q.explanation?`<div class="explanation-text">${E(q.explanation)}</div>`:q.explanation_images?.length?'':'<p>原资料未附可可靠提取的逐题解析。</p>'}</div>`:`${q.guidance?`<details class="annotation"><summary>原资料写作指导${q.guidance_status==='needs_review'?' · 部分文字待核对':''}</summary><p>${E(q.guidance)}</p></details>`:''}${q.model_essay?`<details class="annotation"><summary>原资料范文</summary><p>${E(q.model_essay)}</p></details>`:''}`}<div class="original-links">${sourceLink(q.source_id,q.source_page)}${q.answer_source?sourceLink(q.answer_source.source_id,q.answer_source.pages,'答案出处'):''}${q.explanation_source?sourceLink(q.explanation_source.source_id,q.explanation_source.pages,'解析出处'):''}</div>${window.GREQuestionAI?.panelHTML(q,materials.get(q.material_id))||''}</details>`;}
  function modalHTML(){if(!modal)return '';let content='';const c=current();if(modal.type==='review'&&c){content=`<h2>本节答题总览</h2><p class="muted">点击题号返回修改。浅绿为已作答，★ 为已标记。</p><div class="mock-review-grid">${c.section.ids.map((id,i)=>{const r=c.exam.responses[id]||{selected:[],text:''};return `<button data-mock-jump="${i}" class="${C.complete(questions.get(id),r)?'done':''} ${i===c.exam.index?'active':''}"><strong>${i+1}</strong><small>${r.marked?'★ ':''}${C.complete(questions.get(id),r)?'已作答':'未完成'}</small></button>`;}).join('')}</div><div class="row">${btn('close-modal','继续作答','secondary')}${btn('end-section','提交本节 →','')}</div>`;}
    if(modal.type==='confirm'){content=`<h2>${E(modal.title)}</h2><p class="mock-dialog-copy">${E(modal.message)}</p><div class="row">${btn('close-modal','继续作答','secondary')}${btn(modal.confirm,'确认提交','')}</div>`;}
    if(modal.type==='image')content=`<div class="row space-between"><h2>原题图像</h2>${btn('close-modal','关闭','secondary small')}</div><img class="mock-enlarged-image" src="${E(modal.src)}" alt="放大的原题图像">`;
    if(modal.type==='calculator')content=`<div class="row space-between"><h2>Calculator</h2>${btn('close-modal','关闭','secondary small')}</div><output id="mock-calc-display">${E(calc.value)}</output><div class="mock-calculator-grid">${['MC','MR','M+','M−','(',')','√','C','7','8','9','÷','4','5','6','×','1','2','3','−','0','.','±','+','⌫','='].map(k=>`<button data-mock-calc="${E(k)}" class="${k==='='?'equals':''}">${E(k)}</button>`).join('')}</div><p class="tiny">练习计算器 · 括号与乘除优先 · 最多输入 8 位有效数字。支持平方根、记忆与正负切换。</p>${c&&C.mode(c.q)==='numeric'?btn('calc-transfer','将结果填入当前答案','secondary') :''}`;
    return `<div class="mock-overlay"><section class="mock-dialog ${modal.type==='image'?'image-dialog':''} ${modal.type==='calculator'?'calculator-dialog':''}" role="dialog" aria-modal="true" aria-label="${modal.type==='calculator'?'计算器':modal.type==='image'?'原题图像':'模考操作'}" tabindex="-1">${content}</section></div>`;
  }
  function render(){if(!root)return;visible=true;indexBank();checkClock();if(screen==='exam'&&!state.active)screen=resultId?'result':'setup';document.body.classList.toggle('mock-running',screen==='exam'&&!!state.active);root.innerHTML=(screen==='exam'?examHTML():screen==='result'?resultHTML():setupHTML())+modalHTML();updateClock();if(modal)$('.mock-dialog')?.focus({preventScroll:true});}
  function jump(index){const c=current();if(!c||!Number.isInteger(index)||index<0||index>=c.section.ids.length)return;accrue();c.exam.index=index;modal=null;save();render();window.scrollTo({top:0,behavior:'instant'});}
  function choose(id){checkClock();const c=current();if(!c||screen!=='exam')return;const {q,r}=c,options=q.blank_groups?.length?q.blank_groups.flatMap(g=>g.options):q.options||[];if(!options.some(o=>o.id===id))return;const mode=C.mode(q);if(mode==='blanks'){const group=q.blank_groups.find(g=>g.options.some(o=>o.id===id));r.selected=r.selected.filter(x=>!group.options.some(o=>o.id===x));r.selected.push(id);}else if(mode==='pair'||mode==='multiple'){if(r.selected.includes(id))r.selected=r.selected.filter(x=>x!==id);else if(mode!=='pair'||r.selected.length<2)r.selected.push(id);else{notify('六选二请选择两个答案；请先取消一个选项。');return;}}else r.selected=r.selected.includes(id)?[]:[id];accrue();save();root.querySelectorAll('[data-mock-option]').forEach(el=>{const selected=r.selected.includes(el.dataset.mockOption);el.classList.toggle('selected',selected);el.setAttribute('aria-pressed',selected);});}
  function calcReset(){calc.value='0';calc.tokens=[];calc.entry='';calc.replace=true;calc.memory=0;}
  function calcFormat(v){return !Number.isFinite(v)||Math.abs(v)>99999999?'ERROR':Number(v.toPrecision(8)).toLocaleString('en-US',{useGrouping:false,maximumFractionDigits:20});}
  function calcEvaluate(tokens){let i=0;function atom(){let v;if(tokens[i]==='('){i++;v=sum();if(tokens[i++]!==')')throw Error('括号不匹配');}else{if(typeof tokens[i]!=='number')throw Error('表达式不完整');v=tokens[i++];}return v;}function product(){let v=atom();while(tokens[i]==='×'||tokens[i]==='÷'){const op=tokens[i++],b=atom();v=op==='×'?v*b:v/b;}return v;}function sum(){let v=product();while(tokens[i]==='+'||tokens[i]==='−'){const op=tokens[i++],b=product();v=op==='+'?v+b:v-b;}return v;}const result=sum();if(i!==tokens.length)throw Error('表达式不完整');return result;}
  function calcPress(key){const display=()=>{const el=$('#mock-calc-display');if(el)el.textContent=calc.value;};const commit=()=>{if(calc.entry!==''){calc.tokens.push(Number(calc.entry));calc.entry='';}};
    if(calc.value==='ERROR'&&key!=='C'){if(!/^\d$/.test(key)&&key!=='.')return;calc.tokens=[];calc.entry='';calc.value='0';calc.replace=true;}
    const v=Number(calc.value);try{
      if(/^\d$/.test(key)){if(calc.replace){calc.entry='';calc.replace=false;}const next=calc.entry==='0'?key:calc.entry+key;const significant=next.replace(/[^0-9]/g,'').replace(/^0+/,'');if(significant.length<=8){calc.entry=next;calc.value=calc.entry;}}
      else if(key==='.'){if(calc.replace){calc.entry='';calc.replace=false;}if(!calc.entry.includes('.')){calc.entry=(calc.entry||'0')+'.';calc.value=calc.entry;}}
      else if(key==='C'){calc.value='0';calc.tokens=[];calc.entry='';calc.replace=true;}
      else if(key==='⌫'){calc.entry=(calc.entry||calc.value).slice(0,-1)||'0';if(calc.entry==='-')calc.entry='0';calc.value=calc.entry;calc.replace=false;}
      else if(key==='±'){calc.entry=String(-Number(calc.entry||calc.value));calc.value=calc.entry;calc.replace=false;}
      else if(key==='√'){calc.value=calcFormat(Math.sqrt(Number(calc.entry||calc.value)));calc.entry=calc.value==='ERROR'?'':calc.value;calc.replace=false;}
      else if(key==='MC')calc.memory=0;
      else if(key==='MR'){calc.value=calcFormat(calc.memory);calc.entry=calc.value==='ERROR'?'':calc.value;calc.replace=false;}
      else if(key==='M+'||key==='M−'){const result=calc.memory+(key==='M+'?v:-v);if(calcFormat(result)==='ERROR')throw Error('超出范围');calc.memory=result;}
      else if(key==='('){if(calc.entry!==''||typeof calc.tokens.at(-1)==='number'||calc.tokens.at(-1)===')')throw Error('请先输入运算符');calc.tokens.push('(');calc.replace=true;}
      else if(key===')'){commit();if(calc.tokens.filter(x=>x==='(').length<=calc.tokens.filter(x=>x===')').length)throw Error('括号不匹配');calc.tokens.push(')');calc.replace=true;}
      else if(['+','−','×','÷'].includes(key)){commit();if(!calc.tokens.length)calc.tokens.push(v);if(['+','−','×','÷'].includes(calc.tokens.at(-1)))calc.tokens[calc.tokens.length-1]=key;else calc.tokens.push(key);calc.replace=true;}
      else if(key==='='){commit();if(!calc.tokens.length)calc.tokens.push(v);calc.value=calcFormat(calcEvaluate(calc.tokens));calc.tokens=[];calc.entry='';calc.replace=true;}
    }catch{calc.value='ERROR';calc.tokens=[];calc.entry='';calc.replace=true;}display();
  }
  function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
  async function validateImport(raw){await ready;indexBank();const incoming=validateProgress(typeof raw==='string'?JSON.parse(raw):raw);if(state.active&&incoming.active&&state.active.id!==incoming.active.id)throw Error('当前与备份中各有一场未完成模考。请先完成或中止当前模考，再导入；两份记录均未改动。');return incoming;}
  async function importProgress(raw){const incoming=await validateImport(raw);
    const records=new Map(state.history.map(e=>[e.id,e]));for(const exam of incoming.history){const old=records.get(exam.id);if(!old||exam.endedAt>=old.endedAt)records.set(exam.id,exam);}
    let active=state.active;if(incoming.active&&(!active||incoming.updatedAt>state.updatedAt))active=incoming.active;
    if(active&&records.has(active.id))active=null;state={version:1,active,history:[...records.values()].sort((a,b)=>b.startedAt-a.startedAt),updatedAt:Date.now()};protectedStorage=false;warning='';clockQuestion=null;lastClock=Date.now();await save();checkClock();for(const exam of state.history)record(exam);if(visible){screen='setup';modal=null;render();}return clone(state);
  }
  async function onClick(event){const button=event.target.closest('button');if(!button||!root.contains(button)||button.disabled)return;try{
    const before=current(),identity=before?before.exam.id+':'+before.exam.currentSection+':'+before.q.question_id:null,wasExam=screen==='exam';checkClock();const after=current();if(wasExam&&identity!==(after?after.exam.id+':'+after.exam.currentSection+':'+after.q.question_id:null))return;
    if(button.dataset.mockOption){choose(button.dataset.mockOption);return;}
    if(button.dataset.mockJump!==undefined){jump(Number(button.dataset.mockJump));return;}
    if(button.dataset.mockHistory){accrue();resultId=button.dataset.mockHistory;screen='result';modal=null;render();return;}
    if(button.dataset.mockImage){if(C.localAsset(button.dataset.mockImage)){modal={type:'image',src:button.dataset.mockImage};render();}return;}
    if(button.dataset.mockCalc){calcPress(button.dataset.mockCalc);return;}
    if(button.dataset.subjectChoice){if(['Verbal','Quant'].includes(button.dataset.subjectChoice)){practiceSubject=button.dataset.subjectChoice;render();}return;}
    if(button.dataset.subjectCount){subjectCount=Number(button.dataset.subjectCount);render();return;}
    const action=button.dataset.mockAction;if(!action)return;checkClock();const c=current();
    if(action==='start-subject'){const input=$('#subject-count'),count=Number(input?.value);if(!input?.reportValidity()||!Number.isInteger(count)||count<1||count>100){notify('题量请输入 1 至 100 之间的整数。');return;}if(!bridge?.startSubjectPractice)throw Error('随机练习暂未就绪，请刷新页面。');subjectCount=count;await bridge.startSubjectPractice({subject:practiceSubject,count});}
    else if(action==='resume-subject'){if(bridge?.resumeSubjectPractice)await bridge.resumeSubjectPractice();}
    else if(action==='start'){if(state.active||protectedStorage)return;indexBank();state.active=M().createExam(bank,{order,preferUnseen,seenIds:bridge.getSeenIds?.()||[]},Date.now());screen='exam';resultId=null;modal=null;timerHidden=false;calcReset();clockQuestion=null;await save();render();}
    else if(action==='resume'){if(c){screen='exam';modal=null;render();}}
    else if(action==='setup'){accrue();screen='setup';modal=null;save();render();}
    else if(action==='previous'&&c)jump(c.exam.index-1);
    else if(action==='next'&&c)jump(c.exam.index+1);
    else if(action==='mark'&&c){c.r.marked=!c.r.marked;accrue();save();render();}
    else if(action==='review'&&c){if(c.section.subject==='AWA'){notify('请检查作文内容，再提交本节。');$('#mock-answer-text')?.focus();}else{modal={type:'review'};render();}}
    else if(action==='end-section'&&c){const omitted=c.section.ids.filter(id=>!C.complete(questions.get(id),c.exam.responses[id]||{selected:[],text:''})).length;modal={type:'confirm',title:c.exam.currentSection===4?'提交最后一节？':'提交本节并继续？',message:`${omitted?'本节还有 '+omitted+' 题未完成。':'本节已全部作答。'}提交后无法返回修改，剩余时间不会转移到下一节。`,confirm:'confirm-section'};render();}
    else if(action==='confirm-section'&&c){accrue();resultOf('advance',Date.now(),'manual');modal=null;calcReset();timerHidden=false;if(state.active.endedAt)archive();else save();render();window.scrollTo({top:0,behavior:'instant'});}
    else if(action==='end-exam'&&c){modal={type:'confirm',title:'中止这场模考？',message:'已作答内容会保存并进入复盘。未进入的分节不计为错题；中止后不能继续这场考试。',confirm:'confirm-abort'};render();}
    else if(action==='confirm-abort'&&c){accrue();resultOf('abort',Date.now());archive();render();}
    else if(action==='toggle-time'){timerHidden=!timerHidden;button.textContent=timerHidden?'显示倒计时':'隐藏倒计时';updateClock();}
    else if(action==='calculator'&&c?.section.subject==='Quant'){modal={type:'calculator'};render();}
    else if(action==='close-modal'){modal=null;render();}
    else if(action==='calc-transfer'&&c&&C.mode(c.q)==='numeric'){if(!Number.isFinite(Number(calc.value))){notify('计算器结果不是有效数值。');return;}c.r.text=calc.value;save();modal=null;render();}
    else if(action==='export'){accrue();download('GRE-模考备份-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2));}
    else if(action==='export-original')download('GRE-模考原存档.json',originalBackup||'null');
    else if(action==='import')$('#mock-import-file')?.click();
    else if(action==='export-essay'){const exam=state.history.find(e=>e.id===button.dataset.mockExam),q=questions.get(button.dataset.mockQid),r=exam?.responses[q?.question_id];if(q&&r)download('GRE-Issue-'+date(exam.startedAt).replace(/[/: ]/g,'-')+'.txt',q.question_content+'\n\n'+(q.instructions||'')+'\n\n'+r.text,'text/plain;charset=utf-8');}
  }catch(e){notify(e.message||'操作失败，当前记录已保留。');}}
  function onInput(event){if(event.target.id!=='mock-answer-text')return;checkClock();const c=current();if(!c||c.q.question_id!==event.target.dataset.mockQuestion)return;c.r.text=event.target.value;accrue();save();const counter=$('#mock-word-count');if(counter)counter.textContent=words(c.r.text)+' words';}
  async function onChange(event){if(event.target.id==='subject-count'){const count=Number(event.target.value);if(Number.isInteger(count)&&count>=1&&count<=100){subjectCount=count;root.querySelectorAll('[data-subject-count]').forEach(el=>{const selected=Number(el.dataset.subjectCount)===count;el.classList.toggle('selected',selected);el.setAttribute('aria-pressed',selected);});}return;}if(event.target.id==='mock-order')order=event.target.value;if(event.target.id==='mock-unseen')preferUnseen=event.target.checked;if(event.target.id==='mock-import-file'){const file=event.target.files?.[0];if(!file)return;try{if(file.size>50000000)throw Error('备份文件超过 50 MB，请检查是否选对文件。');await importProgress(await file.text());notify('模考备份已合并，原有历史记录保留。');}catch(e){notify('导入失败：'+e.message);}finally{event.target.value='';}}}
  function onKey(event){if(!modal)return;if(event.key==='Escape'){event.preventDefault();modal=null;render();}if(event.key==='Tab'){const elements=[...$('.mock-dialog').querySelectorAll('button,input,select,textarea,a[href]')].filter(el=>!el.disabled),first=elements[0],last=elements.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement===$('.mock-dialog'))){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}}
  window.GREMockExam={
    mount(container,providedBridge){if(ready){root=container;bridge=providedBridge;return ready;}root=container;bridge=providedBridge;root.addEventListener('click',onClick);root.addEventListener('input',onInput);root.addEventListener('change',onChange);root.addEventListener('keydown',onKey);ready=initialize();return ready;},
    render(){if(!ready)return;return ready.then(()=>render());},
    leave(){if(!visible)return;accrue();visible=false;modal=null;document.body.classList.remove('mock-running');save();},
    getState(){return clone(state);},
    showResult(id){return ready.then(()=>{if(!state.history.some(e=>e.id===id&&e.endedAt))throw Error('未找到已完成的模考记录。');accrue();resultId=id;screen='result';modal=null;render();});},
    persistProgress(){return save({preserveTimestamp:true,silent:true,force:true});},
    exportProgress(){return clone(state);},
    validatePortable(raw,providedBank){return validateProgress(raw,providedBank||bank);},
    async restorePortable(raw){indexBank();const incoming=validateProgress(raw);state=incoming;protectedStorage=false;warning='';clockQuestion=null;lastClock=Date.now();screen='setup';resultId=null;modal=null;await save({preserveTimestamp:true,silent:true,force:true});if(visible)render();return clone(state);},
    validateImport,importProgress
  };
})();
